from odoo import api, fields, models


class XStoreOrderLineLineSubtotal(models.Model):
    _inherit = 'x_store_order_line'

    x_subtotal = fields.Monetary(
        string='Subtotal',
        compute='_compute_x_subtotal',
        store=True,
        currency_field='x_currency_id',
    )

    @api.depends('x_qty', 'x_price_unit')
    def _compute_x_subtotal(self):
        for rec in self:
            rec.x_subtotal = (rec.x_qty or 0.0) * (rec.x_price_unit or 0.0)

from odoo import api, fields, models


class XStoreOrderHeaderTotal(models.Model):
    _inherit = 'x_store_order'

    x_amount_total = fields.Monetary(
        string='Total',
        compute='_compute_x_amount_total',
        store=True,
        currency_field='x_currency_id',
    )

    @api.depends('x_line_ids.x_subtotal')
    def _compute_x_amount_total(self):
        for rec in self:
            rec.x_amount_total = sum(rec.x_line_ids.mapped('x_subtotal'))
